namespace ghidra.app.plugin.match;



using generic.hash;
using generic.hash;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

public class ExactBytesFunctionHasher : AbstractFunctionHasher {
	public static readonly ExactBytesFunctionHasher INSTANCE = new ExactBytesFunctionHasher();

	private MessageDigest digest;

	private ExactBytesFunctionHasher() {
		this.digest = new FNV1a64MessageDigest();
	}

	/* @Override */
	public int commonBitCount(Function funcA, Function funcB, TaskMonitor monitor) {
		return (int) funcA.getBody().getNumAddresses() * 8;
	}

	/* @Override */
	protected long hash(TaskMonitor monitor, List<CodeUnit> units, int byteCount)
    {
		byte[] buffer = new byte[byteCount];
		int offset = 0;
		foreach (CodeUnit codeUnit in units) {
			monitor.checkCancelled();

			try {
				codeUnit.getBytesInCodeUnit(buffer, offset);
			}
			catch (MemoryAccessException e) {
				Msg.warn(this, "Could not get code unit bvtes at " + codeUnit.getAddress());
			}
			offset += codeUnit.getLength();
		}
		if (offset != byteCount) {
			throw new IllegalStateException("did NOT use all the codeUnit buffer bytes");
		}
		lock (digest) {
			digest.reset();
			digest.update(buffer, monitor);
			return digest.digestLong();
		}
	}
}
